        `,armorStyles:[{name:"Scarred",descrip:"A history of violence etched across your skin.",chosen:!1},{name:"Tattooed",descrip:"Images dance across your flesh; a history of who you are and where you've been.",chosen:!1}],rerollable:!0},{tier:1,descrip:`
