        `,armorStyles:[{name:"Ashigaru Armour",descrip:"Leather and iron scales.",chosen:!1},{name:"Kendo Armour",descrip:"Cloth and padded with silk or cotton.",chosen:!1}],rerollable:!0},{tier:2,descrip:`
